// =============================================================
// NODE 2: SIGNAL DETECTION
// n8n settings: Run Once for All Items
// =============================================================
//
// Scores every post from Apify and decides whether it passes.
// Outputs ALL items — the Filter node downstream drops pass: false.
//
// CONFIRMED Apify fields used:
//   videoPlayCount, likesCount, commentsCount, caption,
//   ownerUsername, url, hashtags, timestamp
//
// Fields that DO NOT exist in Apify output (never read these):
//   followerCount, platform, contentType
//
// FOLLOWER COUNT PROXY (Apify does not return follower count):
//   Large accounts are filtered via three combined signals:
//   1. MAX_LIKES     — large accounts consistently exceed 5k likes/post
//   2. MAX_VIEWS     — large accounts always get high absolute view counts
//   3. MIN_ENGAGEMENT_RATE — large accounts have passive audiences,
//                            so their likes/views ratio stays low
// =============================================================

// --- Thresholds (tune these as real data flows in) -----------
const MIN_VIEWS           = 10000;   // floor: need some real traction
const MAX_VIEWS           = 250000;  // ceiling: large account proxy + already viral
const MIN_LIKES           = 500;     // floor: confirm real response
const MAX_LIKES           = 5000;    // ceiling: large account proxy
const MIN_COMMENT_RATE    = 0.002;   // commentsCount / videoPlayCount (tuned from 0.003)
const STRONG_COMMENT_RATE = 0.008;   // threshold for strong signal
const MIN_ENGAGEMENT_RATE = 0.08;    // likesCount / videoPlayCount (raised from 0.05)
const MIN_ASCII_RATIO     = 0.85;    // caption must be ≥85% ASCII (English filter)

// --- Helper: English language check -------------------------
function isEnglish(text) {
  if (!text || text.length === 0) return true;
  const chars = text.split('');
  const asciiCount = chars.filter(c => c.charCodeAt(0) < 128).length;
  return (asciiCount / chars.length) >= MIN_ASCII_RATIO;
}

// --- Helper: safe number ------------------------------------
function num(val) {
  return Number(val) || 0;
}

// --- Main loop ----------------------------------------------
const results = [];

for (const item of $input.all()) {
  const post = item.json;

  const views    = num(post.videoPlayCount);
  const likes    = num(post.likesCount);
  const comments = num(post.commentsCount);
  const caption  = post.caption || '';

  // 1. English filter
  if (!isEnglish(caption)) {
    results.push({ json: { ...post, pass: false, fail_reason: 'non_english' } });
    continue;
  }

  // 2. Views floor
  if (views < MIN_VIEWS) {
    results.push({ json: { ...post, pass: false, fail_reason: 'low_views' } });
    continue;
  }

  // 3. Views ceiling (large account proxy + already-viral filter)
  if (views > MAX_VIEWS) {
    results.push({ json: { ...post, pass: false, fail_reason: 'too_viral_or_large_account' } });
    continue;
  }

  // 4. Likes ceiling (large account proxy)
  if (likes > MAX_LIKES) {
    results.push({ json: { ...post, pass: false, fail_reason: 'large_account' } });
    continue;
  }

  // 5. Likes floor
  if (likes < MIN_LIKES) {
    results.push({ json: { ...post, pass: false, fail_reason: 'low_likes' } });
    continue;
  }

  // 6. Comment rate
  const commentRate = views > 0 ? comments / views : 0;
  if (commentRate < MIN_COMMENT_RATE) {
    results.push({ json: { ...post, pass: false, fail_reason: 'low_comment_rate' } });
    continue;
  }

  // 7. Engagement rate (large account proxy — passive audiences fail this)
  const engagementRate = views > 0 ? likes / views : 0;
  if (engagementRate < MIN_ENGAGEMENT_RATE) {
    results.push({ json: { ...post, pass: false, fail_reason: 'low_engagement' } });
    continue;
  }

  // 8. Assign signal strength
  let signalStrength;
  if (commentRate >= STRONG_COMMENT_RATE && engagementRate >= 0.12) {
    signalStrength = 'strong';
  } else if (commentRate >= STRONG_COMMENT_RATE || engagementRate >= 0.10) {
    signalStrength = 'moderate';
  } else {
    signalStrength = 'early';
  }

  results.push({
    json: {
      ...post,
      pass: true,
      signal_strength: signalStrength,
      comment_rate: commentRate,
      engagement_rate: engagementRate,
    }
  });
}

return results;

// =============================================================
// NODE 4a: PREPARE CLAUDE REQUEST
// n8n settings: Run Once for All Items
// =============================================================
// Runs BEFORE the Claude API HTTP Request node.
// Adds a clean claude_prompt field to each post so the HTTP
// Request node can reference it as a simple expression.
// =============================================================

const results = [];

for (const item of $input.all()) {
  const post = item.json;
  const caption = (post.caption || '').trim();

  // Strip double quotes from caption to keep the JSON body clean
  const safeCaption = caption.substring(0, 500).replace(/"/g, "'");

  const claudePrompt = 'Classify this Instagram caption into one category. Reply with one word only — no punctuation, nothing else.\n\nOptions: storytelling, talking_head, text_over_video\n\nCaption: "' + safeCaption + '"\n\nCategory:';

  results.push({
    json: {
      ...post,
      claude_prompt: claudePrompt,
    },
  });
}

return results;

// =============================================================
// NODE 4b: EXTRACT CLASSIFICATION
// n8n settings: Run Once for All Items
// =============================================================
//
// Runs after the HTTP Request node that called Claude API.
// Extracts the classification label from Claude's response and
// merges it back with the original post data from Signal Filter.
//
// Workflow position: Signal Filter → HTTP Request (Claude) → THIS NODE
// =============================================================

const VALID_TYPES = ['storytelling', 'talking_head', 'text_over_video'];

// Original post data comes from the Signal Filter node
const originalPosts = $('Signal Filter').all();
const claudeResponses = $input.all();

const results = [];

for (let i = 0; i < claudeResponses.length; i++) {
  const claudeResponse = claudeResponses[i].json;
  const originalPost   = (originalPosts[i] || claudeResponses[i]).json;

  let classifiedType = 'unknown';

  try {
    const raw = claudeResponse.content[0].text
      .trim()
      .toLowerCase()
      .replace(/[^a-z_]/g, '');

    if (VALID_TYPES.includes(raw)) {
      classifiedType = raw;
    }
  } catch (e) {
    classifiedType = 'unknown';
  }

  results.push({
    json: {
      ...originalPost,
      classified_type: classifiedType,
    },
  });
}

return results;

// =============================================================
// NODE 5: CONTENT ROUTER
// n8n settings: Run Once for All Items
// =============================================================
//
// Adds a `route` field based on classified_type and passes all
// items through as a single output.
//
// NOTE: Switch node is NOT used — it would not save routing rules
// reliably in n8n v2. This Code node is the replacement.
// =============================================================

const ROUTE_MAP = {
  storytelling:    'storytelling',
  talking_head:    'talking_head',
  text_over_video: 'text_over_video',
};

const results = [];

for (const item of $input.all()) {
  const post = item.json;
  const classifiedType = post.classified_type || 'unknown';

  results.push({
    json: {
      ...post,
      route: ROUTE_MAP[classifiedType] || 'unknown',
    },
  });
}

return results;

// =============================================================
// NODE 6: SMS BUILDER
// n8n settings: Run Once for All Items
// =============================================================
//
// Builds the final message_text field for every passing post.
// Every field access is null-safe — this node will never crash
// on missing or undefined Apify data.
//
// Output field: message_text
// Twilio node expression: {{ $json.message_text }}
//   (nothing after the closing bracket — bug #3 fix)
//
// Platform is hardcoded as "Instagram" because Apify does not
// return a platform field (bug #7 fix).
// =============================================================

// --- Helpers ------------------------------------------------
function safeNum(val) {
  return Number(val) || 0;
}

function fmt(val) {
  return safeNum(val).toLocaleString();
}

// Extract hook: caption text before the hashtag block
function extractHook(caption) {
  if (!caption) return '';
  const lines = caption.split('\n');
  const hookLines = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('#')) break; // stop at first hashtag line
    if (trimmed.length > 0) hookLines.push(trimmed);
  }
  const text = hookLines.join(' ').substring(0, 100).trim();
  return text || caption.substring(0, 100).trim(); // fallback if all lines were hashtags
}

function titleCase(str) {
  return (str || '')
    .replace(/_/g, ' ')
    .replace(/\b\w/g, c => c.toUpperCase());
}

// --- Signal label -------------------------------------------
function getSignalLabel(strength) {
  if (strength === 'strong')   return '🔥 STRONG SIGNAL';
  if (strength === 'moderate') return '📈 SIGNAL DETECTED';
  return '👀 EARLY SIGNAL';
}

// --- Action tip per format ----------------------------------
function getActionTip(classifiedType) {
  if (classifiedType === 'storytelling') {
    return 'Try a 3-part story arc: hook → tension → resolution. Make it personal.';
  }
  if (classifiedType === 'talking_head') {
    return 'Lead with a bold claim or contrarian take in the first 2 seconds.';
  }
  if (classifiedType === 'text_over_video') {
    return 'Use bold text callouts on screen — let the visuals do the talking.';
  }
  return 'Study the hook and pacing — identify what made this land and replicate it.';
}

// --- Main loop ----------------------------------------------
const results = [];

for (const item of $input.all()) {
  const post = item.json;

  const signalStrength  = post.signal_strength  || 'early';
  const classifiedType  = post.classified_type  || 'unknown';
  const username        = post.ownerUsername    || 'unknown';
  const views           = safeNum(post.videoPlayCount);
  const likes           = safeNum(post.likesCount);
  const comments        = safeNum(post.commentsCount);
  const caption         = post.caption          || '';
  const commentRate     = Number(post.comment_rate) || 0;

  const signalLabel  = getSignalLabel(signalStrength);
  const formatLabel  = titleCase(classifiedType);
  const actionTip    = getActionTip(classifiedType);
  const hook         = extractHook(caption);
  const reachPct     = (commentRate * 100).toFixed(2);

  const message_text =
`${signalLabel}
Format: ${formatLabel}
Creator: @${username}
Platform: Instagram

Views: ${fmt(views)}
Likes: ${fmt(likes)}
Comments: ${fmt(comments)}
Reach: ${reachPct}% commented

Hook: ${hook}

Tip: ${actionTip}`;

  results.push({
    json: {
      ...post,
      message_text,
    },
  });
}

return results;
